const tamga_gorsel_t TAMGA_GORSEL[15] = {
    { g48_OTUKEN, g64_OTUKEN, g96_OTUKEN, g128_OTUKEN, p_OTUKEN },
    { g48_UMAY, g64_UMAY, g96_UMAY, g128_UMAY, p_UMAY },
    { g48_DEDEKORKUT, g64_DEDEKORKUT, g96_DEDEKORKUT, g128_DEDEKORKUT, p_DEDEKORKUT },
    { g48_ULGEN, g64_ULGEN, g96_ULGEN, g128_ULGEN, p_ULGEN },
    { g48_TULPAR, g64_TULPAR, g96_TULPAR, g128_TULPAR, p_TULPAR },
    { g48_TIMUR, g64_TIMUR, g96_TIMUR, g128_TIMUR, p_TIMUR },
    { g48_KUT, g64_KUT, g96_KUT, g128_KUT, p_KUT },
    { g48_ASENA, g64_ASENA, g96_ASENA, g128_ASENA, p_ASENA },
    { g48_ERGENEKON, g64_ERGENEKON, g96_ERGENEKON, g128_ERGENEKON, p_ERGENEKON },
    { g48_BITIG, g64_BITIG, g96_BITIG, g128_BITIG, p_BITIG },
    { g48_ULAK, g64_ULAK, g96_ULAK, g128_ULAK, p_ULAK },
    { g48_KERVAN, g64_KERVAN, g96_KERVAN, g128_KERVAN, p_KERVAN },
    { g48_TORE, g64_TORE, g96_TORE, g128_TORE, p_TORE },
    { g48_TAMGA, g64_TAMGA, g96_TAMGA, g128_TAMGA, p_TAMGA },
    { g48_ORKUN, g64_ORKUN, g96_ORKUN, g128_ORKUN, p_ORKUN },
};

static uint32_t gg_harman(uint32_t zem, uint32_t on, int a) {
    if (a >= 255) return on;
    if (a <= 0)   return zem;
    int zr=(int)((zem>>16)&0xFF), zg=(int)((zem>>8)&0xFF), zb=(int)(zem&0xFF);
    int orr=(int)((on>>16)&0xFF), og=(int)((on>>8)&0xFF), ob=(int)(on&0xFF);
    return ((uint32_t)((zr*(255-a)+orr*a)/255)<<16)
         | ((uint32_t)((zg*(255-a)+og *a)/255)<<8)
         |  (uint32_t)((zb*(255-a)+ob *a)/255);
}

void tamga_gorsel_ciz(int x, int y, int id, int boy, int parlaklik) {
    if (id < 0 || id >= 15) return;
    const tamga_gorsel_t *t = &TAMGA_GORSEL[id];
    const uint8_t *m; int n;
    if (boy <= 48)      { m = t->k48;  n = 48;  }
    else if (boy <= 64) { m = t->k64;  n = 64;  }
    else if (boy <= 96) { m = t->k96;  n = 96;  }
    else                { m = t->k128; n = 128; }

    /* Satır satır: toplu oku, harmanla, toplu yaz. Piksel başına
     * fb_get/fb_put çağrısı 128 pikselde çizimi yetişemez kılıyordu. */
    static uint32_t satir[256];
    for (int j = 0; j < n; j++) {
        fb_satir_oku(x, y + j, satir, n);
        for (int i = 0; i < n; i++) {
            uint32_t c2 = t->palet[m[j * n + i]];
            int r=(int)((c2>>16)&0xFF), g=(int)((c2>>8)&0xFF), b=(int)(c2&0xFF);
            int par = (r > g ? (r > b ? r : b) : (g > b ? g : b));
            if (par < 10) continue;
            int a = par * 6;
            if (a > 255) a = 255;
            if (parlaklik > 0) {
                r += (255-r)*parlaklik/255;
                g += (255-g)*parlaklik/255;
                b += (255-b)*parlaklik/255;
                c2 = ((uint32_t)r<<16)|((uint32_t)g<<8)|(uint32_t)b;
            }
            satir[i] = gg_harman(satir[i], c2, a);
        }
        fb_satir_yaz(x, y + j, satir, n);
    }
}